// Encoding checks the value against the schema (ranges, finite numbers) and refuses what the other end would.
inline std::expected<std::string, std::string> encode(const DialogueState& m) {
  json::Value body = detail::to_json(m);
  DialogueState check;
  std::string err;
  if (!detail::from_json(body, check, "dialogue.state body", err)) return std::unexpected(err);
  return json::envelope("dialogue.state", 1, std::move(body));
}
