// Any message in the schema.
inline std::expected<Message, std::string> decode(std::string_view text) {
  return detail::decode_as<Message>(text, "");
}
// What ArgoniaCore accepts from a view: intents only.
inline std::expected<Intent, std::string> decode_intent(std::string_view text) {
  return detail::decode_as<Intent>(text, "a view never sends state; ArgoniaCore accepts intents only");
}
// What a view accepts (mirrored by the TS twin's decodePush).
inline std::expected<Push, std::string> decode_push(std::string_view text) {
  return detail::decode_as<Push>(text, "an intent is never pushed to a view");
}

